mapper.select:
SELECT A.F_TRADE_ID as tradeId, C.ORDER_NO as orderNo, A.PS as ps, A.FINPROD_TYPE2 as finprodTypeTg, A.FINPROD_ID as finprodId, TO_CHAR(A.TRADE_DATE, 'YYYYMMDD') as tradeDate, TO_CHAR(A.SETTLE_DATE, 'YYYYMMDD') as settleDate, A.SHARE_AMT as shareAmt, A.UNIT_CPRICE as unitCprice, A.UNIT_FPRICE as unitFprice, A.FPRICE_AMT as fpriceAmt, A.CPRICE_AMT as cpriceAmt, A.TRADE_AMT as tradeAmt, A.CCY as ccy, B.PORTFOLIO_ID as portfolioId, A.TRADE_MARKET as tradeMarket, E.IS_NET_SETT as isNetSett, E.TRM_FUND_TYPE as trmFundType, E.BOARD as board, SUBSTR(D.FINPROD_MARKET_ID, 0, LENGTH(D.FINPROD_MARKET_ID) - 3) as finprodMarketId, TO_CHAR(F.MPAY_DATE, 'YYYYMMDD') as mPayDate, F.INT_RATE as intRate, SUBSTR(H.PLEDGE_FINPROD_ID, 4, LENGTH(H.PLEDGE_FINPROD_ID) - 3) as pledgeFinprodId, I.SEC_ACCT_ID as secAcctId, I.BOND_ID as bondId, I.TRD_ACCT_ID as trdAcctId, L.SH_SEATNO as shSeatNo, L.SZ_SEATNO as szSeatNo, G.TYPE_6 as type6, G.TYPE_7 as type7, G.TYPE_9 as type9, M.TRADE_PLAT as tradePlat, A.PRIN_AMT as prinAmt, SUBSTR(M.STOCK_ID, 0, LENGTH(M.STOCK_ID) - 3) as tradeFinprodId FROM TRD_PRODUCT_TEMP_DEAL A LEFT JOIN TRD_PRODUCT_TEMP_DEAL_ADD B ON A.TRADE_ID = B.TRADE_ID LEFT JOIN INF_CONTRACT_DETAILFILE C ON A.F_TRADE_ID = C.DEAL_NO LEFT JOIN FIN_PRODUCT D ON A.FINPROD_ID = D.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD E ON A.FINPROD_ID = E.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT F ON A.FINPROD_ID = F.FINPROD_ID AND F.BRANCH = 0 LEFT JOIN FIN_PRODUCT_TYPE G ON A.FINPROD_ID = G.FINPROD_ID AND G.BRANCH = 0 LEFT JOIN FIN_DEAL_PLEDGE H ON F.FINPROD_ID = H.FINPROD_ID AND F.BRANCH = H.BRANCH LEFT JOIN STL_SEC_ACCT_INFO I ON A.SEC_MANAGE_ACCT_ID = I.SEC_ACCT_ID LEFT JOIN PTL_CAPACCT_INFO J ON B.PORTFOLIO_ID = J.PORTFOLIO_ID AND J.ACCT_TYPE = 'A07' AND A.CCY = J.CCY AND I.TRD_ACCT_ID = J.ACCT_NO LEFT JOIN STL_CAPACCT_INFO K ON J.ACCT_NO = K.ACCT_NO LEFT JOIN MST_SALE_DEPARTMENT L ON K.OWN_DEPT = L.SALE_DEPID LEFT JOIN ETR_ENTRUST M ON B.ENTRUST_ID = M.ENTRUST_ID
A.PS IN ('T01', 'T02') AND A.TRADE_DATE = #{dealDate,jdbcType=DATE}
#{portfolioId,jdbcType=VARCHAR}
ORDER BY A.F_TRADE_ID
